import heapq


def _round(n, mode):
    q, r = divmod(n, 10000)
    if mode == "half_up" and 2 * r >= 10000:
        q += 1
    return q


def _ledger(data, sequence_first, discounted_tax):
    cutoff = data.get("cutoff", 10**9)
    winners = {}
    for pos, event in enumerate(data["events"]):
        seq = event.get("sequence", 0)
        if seq > cutoff:
            continue
        event_id = event.get("id", "anonymous:" + str(pos))
        key = ((seq, event.get("revision", 0), pos) if sequence_first
               else (event.get("revision", 0), pos))
        if event_id not in winners or key > winners[event_id][0]:
            winners[event_id] = (key, event)

    balances = dict(data.get("opening", {}))
    mode = data.get("rounding", "floor")
    for _, event in winners.values():
        if event.get("void", False):
            continue
        raw = event["price"] * event.get("quantity", 1)
        discount = min(10000, max(0, event.get("discount_bp", 0)))
        net = _round(raw * (10000 - discount), mode)
        base = net if discounted_tax else raw
        tax = _round(base * event.get("tax_bp", 0), mode)
        amount = net + tax
        if event.get("kind") == "refund":
            amount = -amount
        account = event.get("account", "default")
        currency = event.get("currency", "USD")
        key = account + "|" + currency
        balances[key] = balances.get(key, 0) + amount
    return {"balances": balances}


def _dependencies(data):
    packages = data["packages"]
    names = sorted(packages, reverse=True)
    features = set(data.get("features", []))
    blocked = data.get("blocked", {})
    pins = data.get("pins", {})
    domains = []
    for name in names:
        versions = sorted(row["version"] for row in packages[name]
                          if row["version"] not in blocked.get(name, [])
                          and (name not in pins or row["version"] == pins[name]))
        domains.append([-1] + versions)

    for values in product(*domains):
        chosen = dict(zip(names, values))
        installed = {n for n, v in chosen.items() if v != -1}
        constraints = {n: [] for n in packages}
        for name, bounds in data["roots"].items():
            constraints[name].append(tuple(bounds))

        edges = {n: [] for n in packages}
        reachable = set()
        pending = list(data["roots"])
        valid = True
        while pending and valid:
            name = pending.pop()
            if name in reachable:
                continue
            reachable.add(name)
            version = chosen[name]
            if version == -1 or any(not lo <= version <= hi
                                    for lo, hi in constraints[name]):
                valid = False
                break
            row = next(r for r in packages[name] if r["version"] == version)
            for dep in row.get("deps", []):
                feature = dep.get("feature", "")
                if feature and feature not in features:
                    continue
                other = dep["name"]
                lo, hi = dep["min"], dep["max"]
                constraints[other].append((lo, hi))
                edges[name].append(other)
                pending.append(other)
        if not valid or reachable != installed:
            continue

        state = {}
        def acyclic(node):
            if state.get(node) == 1:
                return False
            if state.get(node) == 2:
                return True
            state[node] = 1
            if any(not acyclic(other) for other in edges[node]):
                return False
            state[node] = 2
            return True

        if all(acyclic(n) for n in reachable):
            return {"versions": {n: chosen[n] for n in packages if n in installed}}
    return {"error": "unsatisfiable"}


def _jobs(data):
    jobs = data["jobs"]
    k = data["k"]
    blocked = set(data.get("blocked", []))
    mandatory = set(data.get("mandatory", []))
    best_value = None
    best_ids = None
    for subset in product((0, 1), repeat=len(jobs)):
        selected = [job for job, take in zip(jobs, subset)
                    if take and job["id"] not in blocked]
        if len(selected) != k:
            continue
        ids = [job["id"] for job in selected]
        if not mandatory.issubset(ids):
            continue
        counts = {}
        for job in selected:
            counts[job["group"]] = counts.get(job["group"], 0) + 1
        if any(not lo <= counts.get(group, 0) <= hi
               for group, (lo, hi) in data.get("quotas", {}).items()):
            continue
        ordered = sorted(selected, key=lambda job: (job["start"], job["end"], job["id"]))
        if any(a["end"] > b["start"] for a, b in zip(ordered, ordered[1:])):
            continue
        value = sum(job["value"] for job in selected)
        sorted_ids = sorted(ids)
        if (best_value is None or value > best_value
                or (value == best_value and sorted_ids > best_ids)):
            best_value, best_ids = value, sorted_ids
    if best_value is None:
        return {"error": "impossible"}
    return {"selected": best_ids, "value": best_value}


def _routes(data):
    required = data.get("required", [])
    bits = {node: 1 << i for i, node in enumerate(required)}
    full = (1 << len(required)) - 1
    graph = [[] for _ in range(data["n"])]
    for edge in data["edges"]:
        graph[edge["u"]].append(edge)
    source = data["source"]
    initial_mask = bits.get(source, 0)
    start = data["start"]
    coupons = data["coupons"]
    initial = (source, initial_mask, 0)
    best = {initial: start}
    queue = [(start, source, initial_mask, 0)]
    while queue:
        time, node, mask, used = heapq.heappop(queue)
        state = (node, mask, used)
        if best.get(state) != time:
            continue
        if node == data["target"] and mask == full and used == coupons:
            return {"arrival": time}
        for edge in graph[node]:
            depart = max(time, edge["open"])
            if depart >= edge["close"]:
                continue
            for spend in (0, 1):
                if used + spend > coupons:
                    continue
                duration = edge["duration"]
                if spend:
                    duration = max(1, duration - edge.get("discount", 0))
                arrival = depart + duration
                if arrival > data["deadline"]:
                    continue
                nxt = edge["v"]
                new_mask = mask | bits.get(nxt, 0)
                new_used = used + spend
                new_state = (nxt, new_mask, new_used)
                if arrival < best.get(new_state, float("inf")):
                    best[new_state] = arrival
                    heapq.heappush(queue, (arrival, nxt, new_mask, new_used))
    return {"arrival": None}


